        if interface.slot_address(80).is_none() { return Err(Error::MissingSlot); }
        if interface.slot_address(88).is_none() { return Err(Error::MissingSlot); }
        if interface.slot_address(96).is_none() { return Err(Error::MissingSlot); }
        Ok(Self { interface })
